package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicInteger;public class PolicyCacheTest{@Test public void boundedCaching(){PolicyCache c=new PolicyCache();AtomicInteger calls=new AtomicInteger();assertTrue(c.get(100,()->calls.incrementAndGet()==1));assertTrue(c.get(349,()->false));assertFalse(c.get(350,()->{calls.incrementAndGet();return false;}));assertEquals(2,calls.get());c.invalidate();assertTrue(c.get(351,()->true));}}